/**
 * The video-widget test fixture — a STILL (constant-frame) video as base64
 * data URIs, plus the exact still frame as a PNG data URI. Auto-generated by
 * scratchpad_agent_15.py (ffmpeg): a 64x48 four-quadrant + white-diagonal
 * pattern (red TL / green TR / blue BL / amber BR) — the SAME layout as the
 * image fixture (checker_png.js) so parity catches any flip, rotation, or
 * channel swap and a human/VLM reads orientation at a glance.
 *
 * WHY STILL: the video PLAYER's current frame is non-deterministic while
 * playing, but a constant-frame clip has ONE frame, so PDF parity (which
 * embeds the current frame) is STABLE. STILL_VIDEO_FRAME_DATA_URI is that one
 * frame as a PNG — the deterministic "grabbed frame" the PDF backend embeds
 * and the GPU external-texture path also shows.
 *
 * Committed so tests/parity/CLI have an offline asset with no asset-server or
 * ffmpeg dependency at test time.
 */

export const STILL_VIDEO_W = 64;
export const STILL_VIDEO_H = 48;

/** H.264/mp4 (Chromium headless decodes this) — the GPU external-texture path. */
export const STILL_VIDEO_MP4_DATA_URI = "data:video/mp4;base64,";

/** VP9/webm (fully open codec) — fallback source. */
export const STILL_VIDEO_WEBM_DATA_URI = "data:video/webm;base64,";

/** The single still frame as a PNG data URI — the deterministic current frame
 * the PDF backend embeds (a STILL video's frame is exactly this). */
export const STILL_VIDEO_FRAME_DATA_URI = "data:image/png;base64,";
